import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Meditation y Concentration","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/magic/meditation-and-concentration.md","filePath":"es/guide/magic/meditation-and-concentration.md"}'),o={name:"es/guide/magic/meditation-and-concentration.md"};function r(s,e,d,c,l,m){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="meditation-and-concentration" tabindex="-1">Meditation y Concentration <a class="header-anchor" href="#meditation-and-concentration" aria-label="Enlace permanente a &quot;Meditation y Concentration&quot;">​</a></h1><p><strong>Estado del diseño: Propuesto.</strong> <strong>Implementación:</strong> no se ha establecido que este rediseño esté implementado. <strong>Disponibilidad:</strong> no se ha establecido que esté disponible en juego. <strong>Verificación:</strong> solo revisión documental. <strong>Revisado:</strong> 2026-10-09 respecto al Batch 04.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Meditation trata de organización, preparación y recuperación de recursos.</li><li>Concentration trata de estabilidad bajo presión; no supone automáticamente otro coste en el límite de habilidades.</li><li>Fizzle e interrupción son distintos, y sus costes exactos siguen sin resolverse.</li></ul><p><a href="/Syrolands-Public/es/game-design/magic.html#meditation-and-concentration">Especificación completa del diseño</a></p><h2 id="at-a-glance" tabindex="-1">De un vistazo <a class="header-anchor" href="#at-a-glance" aria-label="Enlace permanente a &quot;De un vistazo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tema</th><th>Función / límite Propuesto</th></tr></thead><tbody><tr><td>Meditation</td><td>Se propone Meditation como organización mental además de recuperación de recursos: preparar patrones difíciles, organizar Active Memory, recuperar la preparación y usar estados mentales aprendidos con contrapartidas.</td></tr><tr><td>Concentration</td><td>Concentration trata de estabilidad bajo presión. Daño, movimiento, trauma local, ataques repetidos, fatiga, variantes difíciles y ciertos efectos pueden perturbar un lanzamiento. No es automáticamente otra habilidad que consuma el límite de habilidades.</td></tr><tr><td>Fizzle e interrupción</td><td>Fizzle significa no ejecutar correctamente un patrón; interrupción significa que la presión perturba un intento. Sus costes y fórmulas siguen sin decidirse. Tener más maná no haría por sí solo que un mago herido y presionado equivalga a otro sin molestias.</td></tr><tr><td>Preguntas abiertas</td><td>No hay una lista de trances ni bonificación numérica definitiva. La <a href="/Syrolands-Public/es/guide/magic/memory-and-familiarity.html">preparación de memoria</a> y la <a href="/Syrolands-Public/es/guide/combat/stamina-and-reactive-combat.html">presión en combate</a> conectan con esta propuesta sin cambiar el experimento de combate actual.</td></tr></tbody></table><p><a href="/Syrolands-Public/es/game-design/magic.html">Especificación de diseño relacionada</a></p>',8)])])}const g=a(o,[["render",r]]);export{p as __pageData,g as default};
